def estimate_weight_bytes(parameters, bits_per_parameter):
    if parameters < 0 or bits_per_parameter <= 0:
        raise ValueError("Invalid parameters or precision")
    return parameters * bits_per_parameter / 8

params = 7_000_000_000
for bits in (16, 8, 4):
    size_gib = estimate_weight_bytes(params, bits) / (1024 ** 3)
    print(f"{bits}-bit: {size_gib:.2f} GiB (idealized)")
